// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(
        uint64 number_,
        uint64 timestamp_,
        uint256 basefee_,
        bytes32 hash_,
        uint64 seq_,
        bytes32 batcher_,
        uint256 overhead_,
        uint256 scalar_
    ) public {
        // depositorAccount defaults to address(0); the only admissible authorized caller is address(0)
        vm.prank(address(0));
        c.setL1BlockValues(number_, timestamp_, basefee_, hash_, seq_, batcher_, overhead_, scalar_);
        // Reference: setL1BlockValues never writes state, so number() remains 0 for every input.
        assertTrue(c.number() == 0);
    }
}
